-- Generated by the speedrun timer for mathbreakers. Edits are overwritten on every run.
-- Start the timer terminal with class "TIMER_mathbreakers".
hl.window_rule({
	match = {
		class = "^TIMER_mathbreakers$",
	},
	pin = true,
	float = true,
	no_focus = true,
	no_initial_focus = true,
	size = { "940", "220" },
	move = { "0", "0" },
	border_size = 0,
})
local timer_visible = hl.window_rule({
	name = "timer-visible-mathbreakers",
	match = {
		class = "^TIMER_mathbreakers$",
	},
	opacity = "1 override 1 override 1 override",
})

local timer_hidden = hl.window_rule({
	name = "timer-hidden-mathbreakers",
	match = {
		class = "^TIMER_mathbreakers$",
	},
	opacity = "0 override 0 override 0 override",
})

-- Start hidden.
timer_visible:set_enabled(false)
timer_hidden:set_enabled(true)

hl.on("window.active", function(w)
	if w and w.class == "mathbreakers.exe" then
		timer_hidden:set_enabled(false)
		timer_visible:set_enabled(true)
	else
		timer_visible:set_enabled(false)
		timer_hidden:set_enabled(true)
	end
end)
